def q(I):
    h,w=I.shape
    return {'TL':I[:h//2,:w//2],'TR':I[:h//2,w//2:],'BL':I[h//2:,:w//2],'BR':I[h//2:,w//2:]}
# Check hypothesis: out = mode of the four quadrant values; tie -> ? Test exact with simple tie-break rules.
for name,I,O in [('demo1',(I1,O1)),('demo2',(I2,O2)),('demo3',(I3,O3))]:
    Q=q(I); hh,ww=Q['TL'].shape
    mism=[]
    for n in range(hh):
        for m in range(ww):
            vals=[int(Q[k][n,m]) for k in ['TL','TR','BL','BR']]
            c=collections.Counter(vals).most_common()
            if len(c)==1 and c[0][0]==O[n,m]: continue
            if len(c)==1 and c[0][0]!=O[n,m]: mism.append(('mode',tuple(vals),c[0][0],O[n,m]))
            else:
                # count votes for O value
                cv=sum(1 for v in vals if v==O[n,m])
                mv=c[0][1]
                if cv>=mv: mism.append(('tie-favors-O',vals))
